  Array.from($svg.children).forEach(($c) => {
    if (!is_selectable($c)) return;
    if ($selection.has($c) && !evt.ctrlKey) return;

    const bb = $c.getBoundingClientRect();
    if (
      (!$select_inside.checked &&
        bb.top + bb.height > BB.top &&
        bb.left + bb.width > BB.left &&
        bb.bottom - bb.height < BB.bottom &&
        bb.right - bb.width < BB.right) ||
      ($select_inside.checked &&
        bb.top > BB.top &&
        bb.left > BB.left &&
        bb.bottom < BB.bottom &&
        bb.right < BB.right)
    ) {
      evt.ctrlKey ? $selection.delete($c) : $selection.add($c);
    }
  });
  dragging_all_marks_reset();
  $selection.as_ants();
}

export function rgb_hex(rgb) {
  rgb = computed_color(rgb);
  var a = rgb.split('(')[1].split(')')[0].split(',');
  return (
    '#' +
    a
      .map(function (x) {
        x = parseInt(x).toString(16);
        return x.length == 1 ? '0' + x : x;
      })
      .join('')
  );
}

export function valid_color(input) {
  return computed_color(input) !== '';
}

export function computed_color(input) {
  let $div = document.createElement('div');
  document.body.appendChild($div);
  $div.style.color = input;
  let color = window.getComputedStyle($div).color;
  $div.remove();
  return color;
}

export function rgba_color(c) {
  const can = document.createElement('canvas'),
    ctx = can.getContext('2d');
  can.width = can.height = 1;
  ctx.fillStyle = c;
  ctx.fillRect(0, 0, 1, 1); //paint the canvas
  const img = ctx.getImageData(0, 0, 1, 1),
    data = img.data,
    rgba = {
      r: data[0], //0-255 red
      g: data[1], //0-255 green
      b: data[2], //0-255 blue
      a: data[3], //0-255 opacity (0 being transparent, 255 being opaque)
    };
  return rgba;
}

import { $svg } from './dom.js';

export function zoom(scale, pt = null, step = 10) {
  const b = $svg.viewBox.baseVal;
  // svg center
  const cx = b.x + b.width * 0.5,
    cy = b.y + b.height * 0.5;
  if (!pt) pt = { x: cx, y: cy };
  const dx = pt.x - cx,
    dy = pt.y - cy;
  const sw = b.width / scale,
    sh = b.height / scale;
  const sx = dx / step + (b.width - sw) * 0.5,
    sy = dy / step + (b.height - sh) * 0.5;

  // scaled dimensions
  (b.x += sx), (b.y += sy);
  b.width = sw;
  b.height = sh;
}

export function zoom_reset($other = $svg, viewbox = zoom_reset.viewbox) {
  $other.viewBox.baseVal.width = viewbox.width;
  $other.viewBox.baseVal.height = viewbox.height;
  $other.viewBox.baseVal.x = viewbox.x;
  $other.viewBox.baseVal.y = viewbox.y;
}

