  let $pt = $svg.createSVGPoint();
  $pt.x = x;
  $pt.y = y;
  let is_svg = $el === $svg;
  let t = is_svg ? $svg.getScreenCTM() : m2e($el, $svg);
  return $pt.matrixTransform(t.inverse());
}

