    $el.setAttributeNode($attr);
    if ($shape) {
      $shape.style.stroke = 'green';
      $shape.style.strokeWidth = '4';
    }
  });
}

export function deleting() {
  $selection.each(($el) => {
    $selection.delete($el);
    $el.remove();
